    'Wrzuć plik .jar do folderu plugins w zakładce Pliki i zrestartuj serwer 👌' => ['Drop the .jar into the plugins folder in the Files tab and restart the server 👌', 'Leg die .jar im Tab Dateien in den Ordner plugins und starte den Server neu 👌'],
    'Da się dodać mody ze Steam Workshop do Zomboida?' => ['Can I add Steam Workshop mods to Zomboid?', 'Kann ich Steam-Workshop-Mods zu Zomboid hinzufügen?'],
    'Tak - Workshop ID wpisujesz w konfiguracji serwera w panelu, po restarcie mody pobiorą się same.' => ['Yes - put the Workshop IDs in the server config in the panel; after a restart the mods download automatically.', 'Ja - trag die Workshop-IDs in der Serverkonfiguration im Panel ein; nach einem Neustart werden die Mods automatisch geladen.'],
    'Mogę zmienić pakiet w trakcie okresu?' => ['Can I change my plan mid-period?', 'Kann ich den Plan während der Laufzeit wechseln?'],
    'Jasne - w „Twoich serwerach” kliknij „Zmień pakiet”, dopłacasz tylko proporcjonalną różnicę.' => ['Sure - in “Your servers” click “Change plan”; you only pay the pro-rated difference.', 'Klar - klick unter „Deine Server“ auf „Plan wechseln“; du zahlst nur die anteilige Differenz.'],
    'Jak dać znajomemu dostęp do konsoli bez podawania hasła?' => ['How do I give a friend console access without sharing my password?', 'Wie gebe ich einem Freund Konsolenzugriff, ohne mein Passwort zu teilen?'],
    'W panelu zakładka Udostępnij - zapraszasz go i zaznaczasz, co może robić. Hasło zostaje u Ciebie.' => ['Use the Share tab in the panel - invite them and tick what they\'re allowed to do. Your password stays with you.', 'Im Panel unter Teilen - lade ihn ein und wähle aus, was er darf. Dein Passwort bleibt bei dir.'],
    'Zmieniłam wersję i świat zniknął 😭' => ['I changed the version and my world is gone 😭', 'Ich habe die Version gewechselt und meine Welt ist weg 😭'],
    'Spokojnie - w zakładce Backupy przywrócisz kopię sprzed zmiany jednym kliknięciem.' => ['Don\'t worry - in the Backups tab you can restore the pre-change backup in one click.', 'Keine Sorge - im Tab Backups stellst du das Backup von vor der Änderung mit einem Klick wieder her.'],
    'Cennik hostingu gier - DNCT Hosting' => ['Game server hosting pricing - DNCT Hosting', 'Gameserver-Hosting Preise - DNCT Hosting'],
    'Serwer' => ['Server', 'Server'],
    ', który' => [' that', ', der'],
    'nie zwalnia' => ['never slows down', 'nicht bremst'],
    'suwak' => ['slider', 'Schieberegler'],
    'Gotowe plany' => ['Ready-made plans', 'Fertige Pläne'],
    'Wybierz rozmiar - resztę mamy taką samą w każdym.' => ['Pick a size - everything else is the same in every plan.', 'Wähle die Größe - der Rest ist in jedem Plan gleich.'],
    'Zbuduj serwer pod swoją ekipę' => ['Build a server for your crew', 'Bau einen Server für deine Crew'],
    'Przesuń suwak i ustaw liczbę graczy - resztę dobierzemy automatycznie.' => ['Move the slider to set the player count - we\'ll match the rest automatically.', 'Stell mit dem Regler die Spielerzahl ein - den Rest passen wir automatisch an.'],
    'Liczba graczy' => ['Players', 'Spieleranzahl'],
    'Liczba slotów' => ['Slot count', 'Slotanzahl'],
    'slotów' => ['slots', 'Slots'],
    'Okres rozliczeniowy' => ['Billing period', 'Abrechnungszeitraum'],
    'Tydzień' => ['Week', 'Woche'],
    'Miesiąc' => ['Month', 'Monat'],
    'Rok' => ['Year', 'Jahr'],
    '1 miesiąc gratis' => ['1 month free', '1 Monat gratis'],
    'Model rozliczenia' => ['Billing model', 'Abrechnungsmodell'],
    'Jednorazowo' => ['One-off', 'Einmalig'],
    'Abonament' => ['Subscription', 'Abo'],
    'Płacisz raz. Przed końcem okresu przypomnimy o przedłużeniu.' => ['Pay once. We\'ll remind you to renew before the period ends.', 'Einmal zahlen. Vor Ablauf erinnern wir dich an die Verlängerung.'],
    'Odnawia się sam. Rezygnujesz kiedy chcesz, bez pisania do nas.' => ['Renews automatically. Cancel any time, no need to contact us.', 'Verlängert sich automatisch. Jederzeit kündbar, ohne uns zu schreiben.'],
    'Podsumowanie' => ['Summary', 'Zusammenfassung'],
    'Zaloguj się, żeby zamówić' => ['Log in to order', 'Zum Bestellen anmelden'],
    'Przejdź do płatności' => ['Go to payment', 'Zur Zahlung'],
    'W następnym kroku zaakceptujesz' => ['In the next step you\'ll accept the', 'Im nächsten Schritt akzeptierst du die'],
    'i możesz wpisać kod rabatowy. Płatność obsługuje Stripe - nie przechowujemy danych Twojej karty.' => ['and can enter a discount code. Payment is handled by Stripe and charged in PLN - we never store your card details.', 'und kannst einen Rabattcode eingeben. Die Zahlung läuft über Stripe und wird in PLN abgerechnet - wir speichern keine Kartendaten.'],
    'za miesiąc' => ['per month', 'pro Monat'],
    'Abonament wymaga karty - BLIK i przelewy nie obsługują płatności cyklicznych.' => ['A subscription needs a card - BLIK and bank transfers don\'t support recurring payments.', 'Ein Abo braucht eine Karte - BLIK und Überweisungen unterstützen keine wiederkehrenden Zahlungen.'],
    'Zapłacisz kartą lub BLIK-iem. Pełną listę metod zobaczysz w Checkoucie.' => ['You can pay by card or BLIK. The full list of methods is shown at checkout.', 'Du kannst per Karte oder BLIK zahlen. Alle Zahlungsarten siehst du im Checkout.'],
    'Brak miejsca na tym progu' => ['No space at this tier', 'Kein Platz in dieser Stufe'],
    'Ta liczba slotów jest chwilowo niedostępna - wybierz inną.' => ['This slot count is temporarily unavailable - pick another.', 'Diese Slotanzahl ist vorübergehend nicht verfügbar - wähle eine andere.'],
    'Ta liczba slotów jest już niedostępna - wybierz inną.' => ['This slot count is no longer available - pick another.', 'Diese Slotanzahl ist nicht mehr verfügbar - wähle eine andere.'],
    'Dobre na małą, stałą ekipę' => ['Good for a small, regular crew', 'Gut für eine kleine, feste Crew'],
    'W sam raz na granie ze znajomymi' => ['Just right for playing with friends', 'Genau richtig zum Spielen mit Freunden'],
    'Społeczność z regularnym ruchem' => ['A community with regular traffic', 'Eine Community mit regelmäßigem Betrieb'],
    'Duży serwer publiczny' => ['Big public server', 'Großer öffentlicher Server'],
    'Bardzo duży serwer - napisz, dobierzemy sprzęt' => ['Very large server - message us and we\'ll match the hardware', 'Sehr großer Server - schreib uns, wir stimmen die Hardware ab'],
    'Twój wybór' => ['Your choice', 'Deine Wahl'],
    'Wyczyść wybór' => ['Clear selection', 'Auswahl löschen'],
    'Inna gra' => ['Another game', 'Anderes Spiel'],
    'Szukasz innej gry?' => ['Looking for other games?', 'Suchst du ein anderes Spiel?'],
    'Napisz do nas na Discordzie - coś poradzimy. Postawimy serwer pod grę, której nie ma w cenniku, albo powiemy wprost, że się nie da.' => ['Message us on Discord - we\'ll figure something out. We\'ll set up a server for a game that isn\'t on the list, or tell you straight if it can\'t be done.', 'Schreib uns auf Discord - wir finden eine Lösung. Wir richten einen Server für ein Spiel ein, das nicht in der Liste steht, oder sagen dir ehrlich, wenn es nicht geht.'],
    'Najczęściej pytacie o:' => ['Most requested:', 'Am häufigsten gefragt:'],
    'Napisz na Discordzie' => ['Message us on Discord', 'Schreib uns auf Discord'],
    'W każdym planie' => ['In every plan', 'In jedem Plan'],
    'Bez gwiazdek i dopłat' => ['No asterisks, no extra fees', 'Ohne Sternchen und Aufpreise'],
    'Pełny dostęp do panelu i konsoli' => ['Full access to the panel and console', 'Voller Zugriff auf Panel und Konsole'],
    'Dyski SSD, stałe limity RAM-u i CPU' => ['SSDs, fixed RAM and CPU limits', 'SSDs, feste RAM- und CPU-Limits'],
    'Kopie zapasowe w panelu na żądanie' => ['On-demand backups in the panel', 'Backups im Panel auf Abruf'],
    'Ochrona DDoS' => ['DDoS protection', 'DDoS-Schutz'],
    'Własna subdomena i zmiana wersji gry' => ['Your own subdomain and game version switching', 'Eigene Subdomain und Wechsel der Spielversion'],
    'Wsparcie przez Discord, bez systemu biletów' => ['Support on Discord, no ticket system', 'Support auf Discord, ohne Ticketsystem'],
    'Dopłaty za to wszystko' => ['Extra fees for all of this', 'Aufpreis für all das'],
    'Zanim klikniesz' => ['Before you click', 'Bevor du klickst'],
    'Ryzykujesz mniej, niż myślisz' => ['You risk less than you think', 'Du riskierst weniger, als du denkst'],
    'na rezygnację' => ['to cancel', 'zum Rücktritt'],
    'Nie spodobało się? Piszesz na Discordzie i odzyskujesz pieniądze.' => ['Didn\'t like it? Message us on Discord and get your money back.', 'Nicht zufrieden? Schreib uns auf Discord und du bekommst dein Geld zurück.'],
    'Serwery w Polsce' => ['Servers in Poland', 'Server in Polen'],
    'Stoją u nas, nie za granicą. Krótsza droga do serwera to niższy ping i mniej lagów w grze.' => ['Hosted by us in Poland. A shorter route to the server means lower ping and less lag across Central Europe.', 'Bei uns in Polen gehostet. Ein kürzerer Weg zum Server bedeutet niedrigeren Ping und weniger Lag in Mitteleuropa.'],
    'Twarde limity' => ['Hard limits', 'Feste Limits'],
    'Każdy serwer ma w panelu własny, stały limit RAM i CPU.' => ['Every server has its own fixed RAM and CPU limit in the panel.', 'Jeder Server hat im Panel sein eigenes festes RAM- und CPU-Limit.'],
    'Rok taniej o miesiąc' => ['A year costs one month less', 'Ein Jahr kostet einen Monat weniger'],
    'Płatność roczna liczy się jak jedenaście miesięcy, nie dwanaście.' => ['Yearly billing counts as eleven months, not twelve.', 'Jährliche Zahlung zählt als elf Monate, nicht zwölf.'],
    'Ceny brutto w złotych. Szczegółowe warunki świadczenia usług opisuje' => ['Prices in EUR are approximate, converted from Polish złoty (PLN, incl. VAT); you are charged in PLN. Full terms are in the', 'Preise in EUR sind ungefähr, umgerechnet aus polnischen Złoty (PLN, inkl. MwSt.); abgerechnet wird in PLN. Alle Bedingungen stehen in den'],
    'Serwer Minecraft na Paperze, Fabricu albo Forge - od 1,5 do 32 GB RAM. Silnik i wersję gry zmieniasz w panelu jednym kliknięciem, a serwer startuje zaraz po płatności.' => ['A Minecraft server on Paper, Fabric or Forge - from 1.5 to 32 GB RAM. Switch engine and game version in the panel with one click; the server starts right after payment.', 'Ein Minecraft-Server mit Paper, Fabric oder Forge - von 1,5 bis 32 GB RAM. Engine und Spielversion wechselst du im Panel mit einem Klick; der Server startet direkt nach der Zahlung.'],
    'Serwer Build 42 dla Ciebie i znajomych - od 5 do 100 graczy. Wybierasz liczbę slotów, płacisz kartą albo BLIK-iem, a serwer startuje sam, bez czekania na nikogo.' => ['A Build 42 server for you and your friends - 5 to 100 players. Pick the slot count, pay by card or BLIK, and the server starts on its own, no waiting.', 'Ein Build-42-Server für dich und deine Freunde - 5 bis 100 Spieler. Slotanzahl wählen, per Karte oder BLIK zahlen, und der Server startet von selbst, ohne Warten.'],
    'Serwer Vintage Story dla Ciebie i znajomych - od 5 do 100 graczy, zawsze na aktualnej wersji gry. Wybierasz liczbę slotów, płacisz kartą albo BLIK-iem, a serwer startuje sam.' => ['A Vintage Story server for you and your friends - 5 to 100 players, always on the current game version. Pick the slot count, pay by card or BLIK, and the server starts on its own.', 'Ein Vintage-Story-Server für dich und deine Freunde - 5 bis 100 Spieler, immer auf der aktuellen Spielversion. Slotanzahl wählen, per Karte oder BLIK zahlen, und der Server startet von selbst.'],
    'Hosting Minecraft' => ['Minecraft hosting', 'Minecraft-Hosting'],
    'Hosting Project Zomboid' => ['Project Zomboid hosting', 'Project-Zomboid-Hosting'],
    'Hosting Vintage Story' => ['Vintage Story hosting', 'Vintage-Story-Hosting'],
    'Zanim kupisz' => ['Before you buy', 'Bevor du kaufst'],
    'Zobacz pakiety ↓' => ['See plans ↓', 'Pläne ansehen ↓'],
    'Jaki serwer Minecraft wybrać?' => ['Which Minecraft server should you pick?', 'Welchen Minecraft-Server wählen?'],
    'Dobierz serwer Project Zomboid' => ['Pick your Project Zomboid server', 'Wähle deinen Project-Zomboid-Server'],
    'Dobierz serwer Vintage Story do ekipy' => ['Pick a Vintage Story server for your crew', 'Wähle einen Vintage-Story-Server für deine Crew'],
    'Vanilla dla znajomych' => ['Vanilla with friends', 'Vanilla mit Freunden'],
    'Dobry punkt startowy dla kilku osób bez modów.' => ['A good starting point for a few people without mods.', 'Ein guter Start für ein paar Leute ohne Mods.'],
    'Pluginy i większa ekipa' => ['Plugins and a bigger crew', 'Plugins und größere Crew'],
    'Dla serwera z pluginami i kilkunastoma graczami.' => ['For a server with plugins and a dozen or so players.', 'Für einen Server mit Plugins und gut einem Dutzend Spielern.'],
    'Modpack' => ['Modpack', 'Modpack'],
    '8–10 GB RAM lub więcej' => ['8-10 GB RAM or more', '8-10 GB RAM oder mehr'],
    'Wybierz więcej zasobów, jeśli używasz większego modpacka.' => ['Go for more resources if you run a bigger modpack.', 'Nimm mehr Ressourcen, wenn du ein größeres Modpack nutzt.'],
    'Początek' => ['Starting out', 'Einstieg'],
    '5 graczy' => ['5 players', '5 Spieler'],
    '20 graczy' => ['20 players', '20 Spieler'],
    '50 graczy' => ['50 players', '50 Spieler'],
    '6 GB RAM i 3 vCore za 29,99 zł / mies.' => ['6 GB RAM and 3 vCore for 29,99 zł / mo', '6 GB RAM und 3 vCore für 29,99 zł / Monat'],
    '4 GB RAM i 3 vCore za 19,99 zł / mies.' => ['4 GB RAM and 3 vCore for 19,99 zł / mo', '4 GB RAM und 3 vCore für 19,99 zł / Monat'],
    'Większa grupa' => ['Bigger group', 'Größere Gruppe'],
    'Więcej slotów' => ['More slots', 'Mehr Slots'],
    'Przesuń suwak w konfiguratorze — od razu zobaczysz parametry i cenę.' => ['Move the slider in the configurator - you\'ll see specs and price right away.', 'Bewege den Regler im Konfigurator - du siehst Specs und Preis sofort.'],
    'Serwer z modami' => ['Modded server', 'Server mit Mods'],
    'Steam Workshop' => ['Steam Workshop', 'Steam Workshop'],
    'Listę modów i Workshop ID ustawiasz w plikach panelu, a serwer pobierze je po restarcie.' => ['Set the mod list and Workshop IDs in the panel files; the server downloads them after a restart.', 'Mod-Liste und Workshop-IDs stellst du in den Panel-Dateien ein; der Server lädt sie nach einem Neustart.'],
    'Na start' => ['To start', 'Zum Start'],
    'Większa ekipa' => ['Bigger crew', 'Größere Crew'],
    '30,99 zł / mies.; liczbę slotów wybierasz przed zakupem.' => ['30,99 zł / mo; you pick the slot count before buying.', '30,99 zł / Monat; die Slotanzahl wählst du vor dem Kauf.'],
    'Duży świat' => ['Big world', 'Große Welt'],
    '64,99 zł / mies.; dalej zarządzasz wszystkim z jednego panelu.' => ['64,99 zł / mo; you still manage everything from one panel.', '64,99 zł / Monat; du verwaltest weiterhin alles in einem Panel.'],
    'Od zakupu do gry' => ['From purchase to play', 'Vom Kauf zum Spiel'],
    'Wybierasz plan i opłacasz go kartą albo BLIK-iem.' => ['Pick a plan and pay by card or BLIK.', 'Plan wählen und per Karte oder BLIK bezahlen.'],
    'Serwer powstaje automatycznie; adres zobaczysz w panelu.' => ['The server is created automatically; you\'ll see the address in the panel.', 'Der Server wird automatisch erstellt; die Adresse siehst du im Panel.'],
    'W zakładce Wersje (MC) ustawiasz Paper, Fabric, Forge lub inną wersję, a potem dodajesz pluginy albo mody.' => ['In the Versions (MC) tab choose Paper, Fabric, Forge or another version, then add plugins or mods.', 'Im Tab Versionen (MC) wählst du Paper, Fabric, Forge oder eine andere Version und fügst dann Plugins oder Mods hinzu.'],
    'Wybierasz liczbę graczy i opłacasz serwer kartą albo BLIK-iem.' => ['Pick the player count and pay by card or BLIK.', 'Spieleranzahl wählen und per Karte oder BLIK bezahlen.'],
    'Serwer zakłada się automatycznie; przy pierwszym starcie pobiera pliki gry ze Steama.' => ['The server is set up automatically; on first start it downloads the game files from Steam.', 'Der Server wird automatisch eingerichtet; beim ersten Start lädt er die Spieldateien von Steam.'],
    'Dane administratora dostajesz e-mailem, a konfigurację, mody i restart obsługujesz w panelu.' => ['You get the admin login by email; config, mods and restarts are handled in the panel.', 'Die Admin-Daten bekommst du per E-Mail; Konfiguration, Mods und Neustarts erledigst du im Panel.'],
    'Po automatycznym utworzeniu logujesz się do panelu i uruchamiasz świat.' => ['Once it\'s created automatically, log in to the panel and start your world.', 'Nach der automatischen Erstellung meldest du dich im Panel an und startest deine Welt.'],
    'Mody .zip wrzucasz do data/Mods, a administrację nadajesz komendą /op.' => ['Drop .zip mods into data/Mods and grant admin with the /op command.', 'Lege .zip-Mods in data/Mods ab und vergib Adminrechte mit dem Befehl /op.'],
    'Ile kosztuje serwer Minecraft?' => ['How much does a Minecraft server cost?', 'Was kostet ein Minecraft-Server?'],
    'Od 6,99 zł miesięcznie albo 3,99 zł za tydzień (plan Podstawowy: 1,5 GB RAM, 1 vCore). Większe plany mają do 32 GB RAM i 8 vCore. Płatność roczna liczy się jak jedenaście miesięcy.' => ['From 6,99 zł a month or 3,99 zł a week (Podstawowy plan: 1.5 GB RAM, 1 vCore). Bigger plans go up to 32 GB RAM and 8 vCore. Yearly billing counts as eleven months.', 'Ab 6,99 zł pro Monat oder 3,99 zł pro Woche (Plan Podstawowy: 1,5 GB RAM, 1 vCore). Größere Pläne bieten bis zu 32 GB RAM und 8 vCore. Jährliche Zahlung zählt als elf Monate.'],
    'Jaki plan wybrać?' => ['Which plan should I pick?', 'Welchen Plan soll ich wählen?'],
    'Dla kilku znajomych bez modów wystarczą 3-4 GB RAM. Serwer z pluginami dla kilkunastu osób to 6-8 GB, a modpacki zwykle potrzebują 8-10 GB i więcej.' => ['For a few friends without mods, 3-4 GB RAM is enough. A server with plugins for a dozen or so people needs 6-8 GB, and modpacks usually need 8-10 GB or more.', 'Für ein paar Freunde ohne Mods reichen 3-4 GB RAM. Ein Server mit Plugins für gut ein Dutzend Leute braucht 6-8 GB, Modpacks meist 8-10 GB oder mehr.'],
    'Czy mogę zmienić wersję gry albo silnik?' => ['Can I change the game version or engine?', 'Kann ich Spielversion oder Engine wechseln?'],
    'Tak. W panelu, w zakładce Wersje (MC), wybierasz silnik (Paper, Purpur, Fabric, Forge, NeoForge i inne) i wersję Minecrafta. Przed zmianą zrób kopię zapasową.' => ['Yes. In the panel\'s Versions (MC) tab, pick the engine (Paper, Purpur, Fabric, Forge, NeoForge and more) and the Minecraft version. Make a backup before switching.', 'Ja. Im Panel unter Versionen (MC) wählst du die Engine (Paper, Purpur, Fabric, Forge, NeoForge und mehr) und die Minecraft-Version. Mach vor dem Wechsel ein Backup.'],
    'Czy mogę instalować pluginy i mody?' => ['Can I install plugins and mods?', 'Kann ich Plugins und Mods installieren?'],
    'Tak. Pluginy wgrywasz do folderu plugins na serwerze Paper, mody do folderu mods na Fabricu lub Forge - przez menedżer plików w panelu. Instrukcje są w naszych poradnikach.' => ['Yes. Upload plugins to the plugins folder on Paper, mods to the mods folder on Fabric or Forge - via the file manager in the panel. Instructions are in our guides.', 'Ja. Plugins lädst du in den Ordner plugins auf Paper, Mods in den Ordner mods auf Fabric oder Forge - über den Dateimanager im Panel. Anleitungen findest du in unseren Guides.'],
    'Jak szybko serwer jest gotowy?' => ['How fast is the server ready?', 'Wie schnell ist der Server bereit?'],
    'Zakładamy go automatycznie zaraz po płatności kartą lub BLIK-iem. Adres serwera widzisz od razu w panelu, a w zakładce Subdomena możesz ustawić łatwiejszy do zapamiętania adres.' => ['We set it up automatically right after payment by card or BLIK. You see the server address in the panel right away, and in the Subdomain tab you can set an easier-to-remember address.', 'Wir richten ihn direkt nach der Zahlung per Karte oder BLIK automatisch ein. Die Serveradresse siehst du sofort im Panel, und im Tab Subdomain kannst du eine leichter zu merkende Adresse festlegen.'],
    'Ile kosztuje serwer Project Zomboid?' => ['How much does a Project Zomboid server cost?', 'Was kostet ein Project-Zomboid-Server?'],
    'Od 29,99 zł miesięcznie za serwer na 5 graczy (6 GB RAM, 3 vCore). Cena rośnie z liczbą slotów - przesuń suwak wyżej, żeby zobaczyć dokładny pakiet. Płatność roczna liczy się jak jedenaście miesięcy.' => ['From 29,99 zł a month for a 5-player server (6 GB RAM, 3 vCore). The price grows with the slot count - move the slider up to see the exact package. Yearly billing counts as eleven months.', 'Ab 29,99 zł pro Monat für einen Server mit 5 Spielern (6 GB RAM, 3 vCore). Der Preis steigt mit der Slotanzahl - schieb den Regler höher, um das genaue Paket zu sehen. Jährliche Zahlung zählt als elf Monate.'],
    'Która wersja gry jest na serwerze?' => ['Which game version runs on the server?', 'Welche Spielversion läuft auf dem Server?'],
    'Aktualny Build 42 z gałęzi publicznej Steama. Serwer sprawdza aktualizacje przy każdym starcie, więc nie musisz niczego wgrywać ręcznie.' => ['The current Build 42 from Steam\'s public branch. The server checks for updates on every start, so you don\'t have to upload anything by hand.', 'Der aktuelle Build 42 aus dem öffentlichen Steam-Branch. Der Server prüft bei jedem Start auf Updates, du musst also nichts manuell hochladen.'],
    'Czy mogę dodać mody ze Steam Workshop?' => ['Can I add mods from the Steam Workshop?', 'Kann ich Mods aus dem Steam Workshop hinzufügen?'],
    'Tak. Konfigurację serwera (w tym listę modów i Workshop ID) edytujesz w panelu, w menedżerze plików, a po restarcie serwer sam pobierze mody.' => ['Yes. Edit the server config (including the mod list and Workshop IDs) in the panel\'s file manager; after a restart the server downloads the mods itself.', 'Ja. Die Serverkonfiguration (inklusive Mod-Liste und Workshop-IDs) bearbeitest du im Dateimanager des Panels; nach einem Neustart lädt der Server die Mods selbst.'],
    'Zakładamy go automatycznie zaraz po płatności. Pierwsze uruchomienie pobiera grę ze Steama (ok. 7 GB), co zwykle trwa kilka minut. Dane administratora gry dostajesz w mailu.' => ['We set it up automatically right after payment. The first start downloads the game from Steam (about 7 GB), which usually takes a few minutes. You get the game admin login by email.', 'Wir richten ihn direkt nach der Zahlung automatisch ein. Der erste Start lädt das Spiel von Steam (ca. 7 GB), was meist ein paar Minuten dauert. Die Admin-Daten fürs Spiel bekommst du per E-Mail.'],
    'Gdzie stoi serwer?' => ['Where is the server located?', 'Wo steht der Server?'],
    'Na naszym sprzęcie w Polsce, więc ping z polskich łączy jest niski. Serwerem zarządzasz w panelu: konsola, pliki, kopie zapasowe na żądanie i restart jednym kliknięciem.' => ['On our own hardware in Poland, so ping is low across Central Europe. You manage the server in the panel: console, files, on-demand backups and one-click restarts.', 'Auf unserer eigenen Hardware in Polen, daher ist der Ping in Mitteleuropa niedrig. Du verwaltest den Server im Panel: Konsole, Dateien, Backups auf Abruf und Neustart mit einem Klick.'],
    'Ile kosztuje serwer Vintage Story?' => ['How much does a Vintage Story server cost?', 'Was kostet ein Vintage-Story-Server?'],
    'Od 19,99 zł miesięcznie za serwer na 5 graczy (4 GB RAM, 3 vCore). Na 20 graczy to 30,99 zł, na 50 graczy 64,99 zł. Płatność roczna liczy się jak jedenaście miesięcy.' => ['From 19,99 zł a month for a 5-player server (4 GB RAM, 3 vCore). For 20 players it\'s 30,99 zł, for 50 players 64,99 zł. Yearly billing counts as eleven months.', 'Ab 19,99 zł pro Monat für einen Server mit 5 Spielern (4 GB RAM, 3 vCore). Für 20 Spieler 30,99 zł, für 50 Spieler 64,99 zł. Jährliche Zahlung zählt als elf Monate.'],
    'Aktualna stabilna wersja Vintage Story. Serwer działa na .NET 10, którego wymaga najnowsza wersja gry - nie musisz niczego doinstalowywać.' => ['The current stable version of Vintage Story. The server runs on .NET 10, which the latest game version requires - you don\'t need to install anything.', 'Die aktuelle stabile Version von Vintage Story. Der Server läuft auf .NET 10, das die neueste Spielversion braucht - du musst nichts nachinstallieren.'],
    'Czy mogę dodać mody?' => ['Can I add mods?', 'Kann ich Mods hinzufügen?'],
    'Tak. Pliki .zip modów z ModDB (mods.vintagestory.at) wgrywasz w panelu do folderu data/Mods i restartujesz serwer. Opis krok po kroku jest w naszym poradniku.' => ['Yes. Upload the .zip mod files from ModDB (mods.vintagestory.at) to the data/Mods folder in the panel and restart the server. A step-by-step guide is in our guides.', 'Ja. Lade die .zip-Mod-Dateien von ModDB (mods.vintagestory.at) im Panel in den Ordner data/Mods und starte den Server neu. Eine Schritt-für-Schritt-Anleitung findest du in unseren Guides.'],
    'Jak zostać administratorem na serwerze?' => ['How do I become an admin on the server?', 'Wie werde ich Admin auf dem Server?'],
    'W konsoli panelu wpisz /op i nazwę swojego konta Vintage Story, np. /op TwojaNazwa. Serwer sprawdza nazwę w kontach gry, więc musi być prawdziwa.' => ['In the panel console type /op followed by your Vintage Story account name, e.g. /op YourName. The server checks the name against game accounts, so it must be real.', 'Gib in der Panel-Konsole /op und deinen Vintage-Story-Kontonamen ein, z. B. /op DeinName. Der Server prüft den Namen bei den Spielkonten, er muss also echt sein.'],
    'Poradniki:' => ['Guides:', 'Anleitungen:'],
    'jak postawić serwer, dodać mody i ustawić świat' => ['how to set up a server, add mods and configure your world', 'Server einrichten, Mods hinzufügen und Welt einstellen'],
    '· Inne gry:' => ['· Other games:', '· Andere Spiele:'],
    'pełny cennik' => ['full pricing', 'alle Preise'],
    'Zamówienie - DNCT Hosting' => ['Order - DNCT Hosting', 'Bestellung - DNCT Hosting'],
    'Podsumowanie zamówienia serwera gry w DNCT Hosting.' => ['Your game server order summary at DNCT Hosting.', 'Zusammenfassung deiner Gameserver-Bestellung bei DNCT Hosting.'],
    'Zamówienie' => ['Order', 'Bestellung'],
    'Jeszcze tylko dwa wybory' => ['Just two more choices', 'Nur noch zwei Entscheidungen'],
    'Nie tędy droga' => ['Something went wrong', 'Da ist etwas schiefgelaufen'],
    'Wróć do cennika' => ['Back to pricing', 'Zurück zu den Preisen'],
    'Nie znaleziono takiej oferty. Wróć do cennika i wybierz plan jeszcze raz.' => ['We couldn\'t find that offer. Go back to pricing and pick a plan again.', 'Dieses Angebot wurde nicht gefunden. Geh zurück zu den Preisen und wähle erneut einen Plan.'],
    'Nie udało się wczytać oferty. Spróbuj ponownie za chwilę.' => ['We couldn\'t load the offer. Please try again in a moment.', 'Das Angebot konnte nicht geladen werden. Bitte versuch es gleich noch einmal.'],
    'Sprzedaż jest chwilowo wyłączona' => ['Sales are temporarily paused', 'Der Verkauf ist vorübergehend pausiert'],
    'Trwa przerwa techniczna - nie przyjmujemy w tej chwili nowych zamówień. Konfigurację poniżej możesz sobie obejrzeć, ale przycisk płatności jest nieaktywny.' => ['We\'re in a maintenance break - we\'re not taking new orders right now. You can look at the configuration below, but the payment button is disabled.', 'Gerade läuft eine Wartungspause - wir nehmen momentan keine neuen Bestellungen an. Du kannst dir die Konfiguration unten ansehen, aber der Zahlungsbutton ist deaktiviert.'],
    'Gra' => ['Game', 'Spiel'],
    'Pakiet' => ['Package', 'Paket'],
    'Dysk' => ['Storage', 'Speicher'],
    'Okres' => ['Period', 'Laufzeit'],
    '/ tydzień' => ['/ week', '/ Woche'],
    '/ miesiąc' => ['/ month', '/ Monat'],
    '/ rok' => ['/ year', '/ Jahr'],
    'jednorazowo' => ['one-off', 'einmalig'],
    'Serwer zakładamy na Twoim koncie w panelu - dlatego potrzebujemy logowania.' => ['We create the server on your panel account - that\'s why you need to log in.', 'Wir legen den Server auf deinem Panel-Konto an - deshalb musst du dich anmelden.'],
    'Kod rabatowy' => ['Discount code', 'Rabattcode'],
    '(opcjonalnie)' => ['(optional)', '(optional)'],
    'np. kod twórcy' => ['e.g. a creator code', 'z. B. ein Creator-Code'],
    'Warunki zamówienia' => ['Order terms', 'Bestellbedingungen'],
    '@zgoda-akceptuje' => ['I accept the', 'Ich akzeptiere die'],
    'Regulamin DNCT' => ['DNCT Terms of Service (in Polish)', 'AGB von DNCT (auf Polnisch)'],
    'Żądam rozpoczęcia usługi niezwłocznie po potwierdzeniu płatności. Przyjmuję do wiadomości, że po pełnym wykonaniu usługi mogę utracić prawo odstąpienia, jeżeli są spełnione warunki ustawowe.' => ['I request that the service starts immediately after payment is confirmed. I acknowledge that once the service has been fully performed I may lose my right of withdrawal, if the statutory conditions are met.', 'Ich verlange, dass die Leistung unmittelbar nach Bestätigung der Zahlung beginnt. Mir ist bekannt, dass ich nach vollständiger Erbringung der Leistung mein Widerrufsrecht verlieren kann, sofern die gesetzlichen Voraussetzungen erfüllt sind.'],
    'Bez tego żądania zapłacisz teraz, a usługę uruchomimy po 14 dniach od zawarcia umowy.' => ['Without this request you pay now and we start the service 14 days after the contract is concluded.', 'Ohne diese Erklärung zahlst du jetzt und wir starten die Leistung 14 Tage nach Vertragsschluss.'],
    'Płatność obsługuje Stripe - nie przechowujemy danych Twojej karty.' => ['Payment is handled by Stripe and charged in Polish złoty (PLN) - we never store your card details.', 'Die Zahlung läuft über Stripe und wird in polnischen Złoty (PLN) abgerechnet - wir speichern keine Kartendaten.'],
    'Przekierowuję do płatności…' => ['Redirecting to payment…', 'Weiterleitung zur Zahlung…'],
    'Nie udało się rozpocząć płatności.' => ['We couldn\'t start the payment.', 'Die Zahlung konnte nicht gestartet werden.'],
    'Brak połączenia z serwerem. Sprawdź internet i spróbuj ponownie.' => ['No connection to the server. Check your internet and try again.', 'Keine Verbindung zum Server. Prüf deine Internetverbindung und versuch es erneut.'],
    'Zaakceptuj Regulamin, aby przejść do płatności.' => ['Accept the Terms of Service to continue to payment.', 'Akzeptiere die AGB, um zur Zahlung zu gelangen.'],
    'Dziękujemy za zamówienie - DNCT Hosting' => ['Thank you for your order - DNCT Hosting', 'Danke für deine Bestellung - DNCT Hosting'],
    'Potwierdzenie zamówienia serwera gry w DNCT Hosting.' => ['Game server order confirmation at DNCT Hosting.', 'Bestätigung deiner Gameserver-Bestellung bei DNCT Hosting.'],
    'Brakuje identyfikatora płatności' => ['Payment ID missing', 'Zahlungs-ID fehlt'],
    'Ten adres otwiera się normalnie po powrocie ze Stripe\'a. Jeśli trafiłeś tu z zakładki, sprawdź swoje zamówienia albo napisz do nas na Discordzie.' => ['This page normally opens after you return from Stripe. If you came here from a bookmark, check your orders or message us on Discord.', 'Diese Seite öffnet sich normalerweise nach der Rückkehr von Stripe. Wenn du über ein Lesezeichen hier bist, prüf deine Bestellungen oder schreib uns auf Discord.'],
    'Płatność przyjęta' => ['Payment received', 'Zahlung erhalten'],
    'Zakładamy Twój serwer - to zwykle kilkanaście sekund. Nie zamykaj tej strony.' => ['We\'re setting up your server - this usually takes a few seconds. Don\'t close this page.', 'Wir richten deinen Server ein - das dauert meist ein paar Sekunden. Schließ diese Seite nicht.'],
    'Dopisujemy kolejny okres do Twojego serwera - to potrwa chwilę.' => ['We\'re adding another period to your server - this will take a moment.', 'Wir verlängern deinen Server um eine weitere Laufzeit - das dauert einen Moment.'],
    'Przestawiamy zasoby Twojego serwera - to potrwa chwilę.' => ['We\'re switching your server\'s resources - this will take a moment.', 'Wir stellen die Ressourcen deines Servers um - das dauert einen Moment.'],
    'Kończymy zamówienie - to potrwa chwilę.' => ['We\'re finishing your order - this will take a moment.', 'Wir schließen deine Bestellung ab - das dauert einen Moment.'],
    'Otwórz panel' => ['Open panel', 'Panel öffnen'],
    'Serwer jest gotowy' => ['Your server is ready', 'Dein Server ist bereit'],
    'Wszystko działa - serwer czeka w panelu.' => ['Everything works - your server is waiting in the panel.', 'Alles läuft - dein Server wartet im Panel.'],
    'Płatność jest przyjęta, ale serwer nadal się zakłada. Sprawdź panel za chwilę - albo napisz do nas.' => ['Payment is received, but the server is still being set up. Check the panel in a moment - or message us.', 'Die Zahlung ist eingegangen, aber der Server wird noch eingerichtet. Schau gleich ins Panel - oder schreib uns.'],
    'Płatność przyjęta, serwer w trakcie' => ['Payment received, server in progress', 'Zahlung erhalten, Server in Arbeit'],
    'Pieniądze doszły, ale automat nie dokończył zakładania serwera. Wiemy o tym i zajmiemy się tym ręcznie - napisz na Discordzie, jeśli chcesz przyspieszyć.' => ['Your payment arrived, but the automation didn\'t finish setting up the server. We know about it and will handle it manually - message us on Discord if you want to speed things up.', 'Deine Zahlung ist angekommen, aber die Automatik hat den Server nicht fertig eingerichtet. Wir wissen davon und kümmern uns manuell - schreib uns auf Discord, wenn es schneller gehen soll.'],
    'Serwer przedłużony' => ['Server extended', 'Server verlängert'],
    'Dopisaliśmy kolejny okres - serwer działa dalej bez przerwy.' => ['We\'ve added another period - your server keeps running without interruption.', 'Wir haben eine weitere Laufzeit hinzugefügt - dein Server läuft ohne Unterbrechung weiter.'],
    'Płatność jest przyjęta, dopisujemy dni do serwera. Odśwież za chwilę swoje serwery.' => ['Payment received, we\'re adding days to your server. Refresh your servers in a moment.', 'Zahlung erhalten, wir fügen deinem Server Tage hinzu. Aktualisiere gleich deine Server.'],
    'Płatność przyjęta, przedłużenie w trakcie' => ['Payment received, extension in progress', 'Zahlung erhalten, Verlängerung in Arbeit'],
    'Pieniądze doszły, ale automat nie dopisał okresu. Zajmiemy się tym ręcznie - napisz na Discordzie, jeśli to pilne.' => ['Your payment arrived, but the automation didn\'t add the period. We\'ll handle it manually - message us on Discord if it\'s urgent.', 'Deine Zahlung ist angekommen, aber die Automatik hat die Laufzeit nicht hinzugefügt. Wir kümmern uns manuell - schreib uns auf Discord, wenn es dringend ist.'],
    'Pakiet zmieniony' => ['Plan changed', 'Plan gewechselt'],
    'Nowe zasoby są już przypisane do serwera. Zrestartuj go, żeby z nich skorzystał.' => ['The new resources are assigned to your server. Restart it to use them.', 'Die neuen Ressourcen sind deinem Server zugewiesen. Starte ihn neu, um sie zu nutzen.'],
    'Płatność jest przyjęta, przestawiamy zasoby serwera. Odśwież za chwilę swoje serwery.' => ['Payment received, we\'re switching your server\'s resources. Refresh your servers in a moment.', 'Zahlung erhalten, wir stellen die Ressourcen deines Servers um. Aktualisiere gleich deine Server.'],
    'Płatność przyjęta, zmiana w trakcie' => ['Payment received, change in progress', 'Zahlung erhalten, Wechsel in Arbeit'],
    'Pieniądze doszły, ale automat nie przestawił zasobów. Zajmiemy się tym ręcznie - napisz na Discordzie.' => ['Your payment arrived, but the automation didn\'t switch the resources. We\'ll handle it manually - message us on Discord.', 'Deine Zahlung ist angekommen, aber die Automatik hat die Ressourcen nicht umgestellt. Wir kümmern uns manuell - schreib uns auf Discord.'],
    'To trwa dłużej niż zwykle' => ['This is taking longer than usual', 'Das dauert länger als gewöhnlich'],
    'Nie znaleźliśmy tego zamówienia. Napisz do nas na Discordzie - sprawdzimy ręcznie.' => ['We couldn\'t find this order. Message us on Discord - we\'ll check manually.', 'Wir haben diese Bestellung nicht gefunden. Schreib uns auf Discord - wir prüfen es manuell.'],
    'Brak połączenia z serwerem. Sprawdź panel za chwilę.' => ['No connection to the server. Check the panel in a moment.', 'Keine Verbindung zum Server. Schau gleich ins Panel.'],
