    'Opłacone do' => ['Paid until', 'Bezahlt bis'],
    'Pozostało' => ['Remaining', 'Verbleibend'],
    'ostatni dzień' => ['last day', 'letzter Tag'],
    'Zawieszenie' => ['Suspension', 'Sperrung'],
